const request = $('Firebase - Get Recipe Request').item.json;
const recipesById = $('Firebase - Get Recipes').item.json;

const requestedNames = request.requestedIngredientNames ?? [];
const minPercent = request.minIngredientMatchPercent ?? 70;
const maxExtras = request.maxExtraBasicIngredients ?? 3;

const matches = Object.values(recipesById ?? {})
  .filter((recipe) => matchesPreferences(recipe, request))
  .filter((recipe) => matchesIngredients(recipe, requestedNames, minPercent, maxExtras))
  .sort(sortMatches)
  .slice(0, 3);

return [
  {
    json: {
      requestId: $('Webhook - Recipe Generation').item.json.body.requestId,
      matchedRecipeIds: matches.map((recipe) => recipe.id),
      matchedRecipeTitles: matches.map((recipe) => recipe.title),
      usedIngredientPercent: getBestUsedPercent(matches, requestedNames),
      status: matches.length > 0 ? 'completed' : 'failed',
      error: matches.length > 0 ? null : 'noMatchingRecipes',
    },
  },
];

/** Checks all preference rules for one recipe. */
function matchesPreferences(recipe, requestData) {
  return recipe.cuisine === requestData.cuisine
    && matchesDiet(recipe.diet, requestData.diet)
    && matchesCookingTime(recipe.cookingTime, requestData.cookingTime)
    && matchesCookingPersons(recipe, requestData.cookingPersons);
}

/** Checks whether the recipe diet is compatible with the selection. */
function matchesDiet(recipeDiet, selectedDiet) {
  if (selectedDiet === 'none') {
    return true;
  }

  if (selectedDiet === 'vegetarian') {
    return recipeDiet === 'vegetarian' || recipeDiet === 'vegan';
  }

  return recipeDiet === selectedDiet;
}

/** Allows recipes that need the same or less cooking time. */
function matchesCookingTime(recipeTime, selectedTime) {
  const ranks = { quick: 1, medium: 2, complex: 3 };

  return ranks[recipeTime] <= ranks[selectedTime];
}

/** Checks whether the requested cooking persons are allowed. */
function matchesCookingPersons(recipe, cookingPersons) {
  const min = recipe.cookingPersonsMin ?? recipe.cookingPersons ?? 1;
  const max = recipe.cookingPersonsMax ?? recipe.cookingPersons ?? 4;

  return cookingPersons >= min && cookingPersons <= max;
}

/** Checks ingredient usage and allowed extra ingredients. */
function matchesIngredients(recipe, requestedNames, minPercent, maxExtras) {
  const requiredNames = getRequiredIngredientNames(recipe);
  const extraNames = recipe.extraBasicIngredientNames ?? [];
  const percent = getUsedIngredientPercent(requiredNames, requestedNames);

  return percent >= minPercent && extraNames.length <= maxExtras;
}

/** Gets required recipe ingredients with a safe fallback. */
function getRequiredIngredientNames(recipe) {
  if (recipe.requiredIngredientNames?.length) {
    return recipe.requiredIngredientNames;
  }

  return Object.keys(recipe.ingredientIndex ?? {});
}

/** Calculates the percentage of requested ingredients used. */
function getUsedIngredientPercent(requiredNames, requestedNames) {
  const usedCount = requestedNames.filter((name) => requiredNames.includes(name)).length;

  return requestedNames.length ? Math.round((usedCount / requestedNames.length) * 100) : 0;
}

/** Returns the highest ingredient usage among all matches. */
function getBestUsedPercent(matches, requestedNames) {
  if (!matches.length) {
    return 0;
  }

  const percents = matches.map((recipe) =>
    getUsedIngredientPercent(getRequiredIngredientNames(recipe), requestedNames),
  );

  return Math.max(...percents);
}

/** Sorts matching recipes by likes and then id. */
function sortMatches(first, second) {
  const likeDifference = Number(second.likes ?? 0) - Number(first.likes ?? 0);

  return likeDifference || String(first.id).localeCompare(String(second.id));
}

const crypto = require('crypto');

const webhook = $input.first().json;
const body = webhook.body ?? {};
const headers = webhook.headers ?? {};

const mode = body.mode === 'quota-status' ? 'quota-status' : 'generate';
const requestId = typeof body.requestId === 'string' ? body.requestId : null;
const ip = headers['cf-connecting-ip'] ?? '';

if (!ip) {
  throw new Error('Missing client IP header.');
}

if (mode === 'generate' && !requestId) {
  throw new Error('Missing recipe request id.');
}

const dayKey = new Date().toISOString().slice(0, 10);
const ipHash = crypto.createHash('sha256').update(ip).digest('hex');

return [
  {
    json: {
      mode,
      requestId,
      dayKey,
      ipHash,
    },
  },
];

const quota = $('Code - Build Quota Status').item.json;
const matchResult = $('Code - Match Recipes').item.json;

const maxResultCount = 3;
const matchedRecipeIds = (matchResult.matchedRecipeIds ?? []).slice(0, maxResultCount);
const missingResultCount = Math.max(0, maxResultCount - matchedRecipeIds.length);

const generationTargetCount = Math.min(
  missingResultCount,
  quota.remainingGenerations,
);

const canGenerate = generationTargetCount > 0;

const error =
  missingResultCount > 0 && generationTargetCount === 0
    ? quota.quotaError
    : null;

return [
  {
    json: {
      ...quota,
      maxResultCount,
      matchedRecipeIds,
      matchedRecipeTitles: matchResult.matchedRecipeTitles ?? [],
      matchedUsedIngredientPercent:
        matchResult.usedIngredientPercent ?? 0,
      missingResultCount,
      generationTargetCount,
      canGenerate,
      error,
    },
  },
];

