const context = $('Code - Prepare Quota Context').item.json;
const ipQuota = $('Firebase - Get IP Quota').item.json ?? {};
const systemQuota = $('Firebase - Get System Quota').item.json ?? {};

const ipCount = Number(ipQuota.used ?? 0);
const systemCount = Number(systemQuota.used ?? 0);

const ipLimit = 3;
const systemLimit = 12;

const ipRemaining = Math.max(0, ipLimit - ipCount);
const systemRemaining = Math.max(0, systemLimit - systemCount);
const remainingGenerations = Math.min(ipRemaining, systemRemaining);

const quotaError = getQuotaError(ipCount, systemCount, ipLimit, systemLimit);

return [
  {
    json: {
      ...context,
      ipCount,
      systemCount,
      ipLimit,
      systemLimit,
      remainingGenerations,
      quotaError,
    },
  },
];

/** Returns the active quota error or null when quota is available. */
function getQuotaError(ipCount, systemCount, ipLimit, systemLimit) {
  if (ipCount >= ipLimit) {
    return 'ipQuotaExceeded';
  }

  return systemCount >= systemLimit ? 'systemQuotaExceeded' : null;
}

