const BASIC_NAMES = new Set(['salt', 'pepper', 'oil', 'water', 'flour', 'butter']);

const VEGAN_FORBIDDEN = new Set([
  'egg', 'milk', 'butter', 'cheese', 'cream', 'yogurt', 'honey', 'paneer',
  'feta', 'mozzarella', 'ricotta', 'parmesan', 'goat-cheese', 'blue-cheese',
  'chicken', 'beef', 'pork', 'fish', 'tuna', 'salmon', 'shrimp', 'bacon', 'ham',
]);

const VEGETARIAN_FORBIDDEN = new Set([
  'chicken', 'beef', 'pork', 'fish', 'tuna', 'salmon', 'shrimp', 'bacon', 'ham',
]);

const KETO_FORBIDDEN = new Set([
  'rice', 'pasta', 'bread', 'potato', 'flour', 'sugar', 'noodle', 'tortilla',
]);

const request = $('Firebase - Get Recipe Request').item.json;
const plan = $('Code - Check Quota').item.json;
const existingRecipes = Object.values($('Firebase - Get Recipes').item.json ?? {});
const payload = readPayload($input.first().json);

const candidates = getCandidates(payload, plan.generationTargetCount);
const result = validateGeneratedRecipes(candidates, request, existingRecipes);

return [{ json: { ...plan, ...result } }];

/** Reads direct JSON or a JSON string from Gemini output. */
function readPayload(value) {
  const source = value.content?.parts?.[0]?.text
    ?? value.output
    ?? value.text
    ?? value.response
    ?? value.content
    ?? value;

  return typeof source === 'string' ? parsePayload(source) : source;
}

/** Parses one possible JSON response string. */
function parsePayload(value) {
  const clean = value
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    return JSON.parse(clean);
  } catch {
    return null;
  }
}

/** Returns at most the number of candidates requested by the generation plan. */
function getCandidates(payload, targetCount) {
  if (!payload || typeof payload !== 'object' || payload.valid === false) {
    return [];
  }

  return payload.valid === true && Array.isArray(payload.recipes)
    ? payload.recipes.slice(0, targetCount)
    : [];
}

/** Validates all candidates and removes existing or internal duplicates. */
function validateGeneratedRecipes(candidates, requestData, existingRecipes) {
  const validRecipes = [];
  const errors = [];

  const seenTitles = new Set(
    existingRecipes
      .map((recipe) => normalizeTitle(recipe?.title))
      .filter(Boolean),
  );

  const seenSignatures = new Set(
    existingRecipes
      .map(getRecipeSignature)
      .filter(Boolean),
  );

  for (const recipe of candidates) {
    const validation = validateRecipe(recipe, requestData);

    if (!validation.isValid) {
      errors.push(validation.error);
      continue;
    }

    const title = normalizeTitle(recipe.title);
    const signature = getRecipeSignature(recipe);

    if (seenTitles.has(title) || seenSignatures.has(signature)) {
      errors.push('duplicateGeneratedRecipe');
      continue;
    }

    seenTitles.add(title);
    seenSignatures.add(signature);
    validRecipes.push(validation.recipe);
  }

  return {
    validRecipes,
    generatedUsedIngredientPercent: validRecipes.length
      ? Math.max(
          ...validRecipes.map((recipe) =>
            getUsedIngredientPercent(recipe, requestData),
          ),
        )
      : 0,
    error: validRecipes.length
      ? null
      : (errors[0] ?? 'invalidGeneratedRecipe'),
  };
}

/** Validates one generated recipe against all request rules. */
function validateRecipe(recipe, requestData) {
  if (!hasBaseFields(recipe) || !matchesRequest(recipe, requestData)) {
    return invalidResult('invalidGeneratedRecipe');
  }

  const ingredientResult = validateIngredientRules(recipe, requestData);
  const stepsValid = hasValidSteps(recipe.steps, requestData.cookingPersons);
  const metadataValid = hasValidMetadata(recipe);
  const dietValid = respectsDiet(recipe, requestData.diet);

  return ingredientResult.valid && stepsValid && metadataValid && dietValid
    ? validResult(recipe)
    : invalidResult('invalidGeneratedRecipe');
}

/** Checks required recipe fields before deeper validation. */
function hasBaseFields(recipe) {
  return isText(recipe?.title)
    && isText(recipe?.description)
    && Array.isArray(recipe?.ingredients)
    && Array.isArray(recipe?.requiredIngredientNames)
    && Array.isArray(recipe?.extraBasicIngredientNames)
    && Array.isArray(recipe?.steps)
    && Array.isArray(recipe?.tags)
    && Array.isArray(recipe?.searchKeywords);
}

/** Checks exact preference values from the original request. */
function matchesRequest(recipe, requestData) {
  return recipe.baseServings === requestData.servings
    && recipe.cookingPersons === requestData.cookingPersons
    && recipe.cookingPersonsMin === requestData.cookingPersons
    && recipe.cookingPersonsMax === requestData.cookingPersons
    && recipe.cookingTime === requestData.cookingTime
    && recipe.cuisine === requestData.cuisine
    && recipe.diet === requestData.diet;
}

/** Validates used ingredients, extras, and minimum match percentage. */
function validateIngredientRules(recipe, requestData) {
  const state = getIngredientState(recipe, requestData);
  const extrasValid = hasAllowedExtras(state, requestData);
  const requiredValid = hasValidRequiredNames(state);
  const uniqueNames = state.names.length === recipe.ingredients.length;
  const minimumReached = state.percent >= requestData.minIngredientMatchPercent;

  return {
    valid:
      state.names.length > 0
      && uniqueNames
      && state.itemsValid
      && extrasValid
      && requiredValid
      && minimumReached,
  };
}

/** Creates normalized ingredient validation data. */
function getIngredientState(recipe, requestData) {
  const names = unique(recipe.ingredients.map((item) => item.normalizedName));
  const userNames = unique(requestData.requestedIngredientNames ?? []);
  const extras = unique(recipe.extraBasicIngredientNames ?? []);
  const required = unique(recipe.requiredIngredientNames ?? []);
  const usedNames = names.filter((name) => userNames.includes(name));
  const generatedExtras = names.filter((name) => !userNames.includes(name));

  return {
    names,
    userNames,
    extras,
    required,
    usedNames,
    generatedExtras,
    percent: getPercent(usedNames, userNames),
    itemsValid: recipe.ingredients.every(isValidIngredient),
  };
}

/** Checks that all generated extras are allowed basic ingredients. */
function hasAllowedExtras(state, requestData) {
  return sameMembers(state.generatedExtras, state.extras)
    && state.generatedExtras.every(isBasic)
    && state.extras.every(isNormalizedName)
    && state.generatedExtras.length <= requestData.maxExtraBasicIngredients;
}

/** Checks required user ingredients against the recipe ingredient list. */
function hasValidRequiredNames(state) {
  return state.required.every((name) => state.userNames.includes(name))
    && state.required.every(isNormalizedName)
    && state.usedNames.every((name) => state.required.includes(name));
}

/** Checks one ingredient object. */
function isValidIngredient(item) {
  return isText(item?.name)
    && isNormalizedName(item?.normalizedName)
    && Number.isFinite(item?.amount)
    && item.amount > 0
    && ['gram', 'ml', 'piece'].includes(item?.unit);
}

/** Checks exact step count, order, and chef number range. */
function hasValidSteps(steps, cookingPersons) {
  if (steps.length < 4 || steps.length > 6) {
    return false;
  }

  return steps.every(
    (step, index) =>
      step.order === index + 1
      && Number.isInteger(step.chefNumber)
      && step.chefNumber >= 1
      && step.chefNumber <= cookingPersons
      && isText(step.text),
  );
}

/** Checks nutrition, tags, and search keyword requirements. */
function hasValidMetadata(recipe) {
  return hasValidNutrition(recipe.nutrition)
    && hasValidTags(recipe.tags)
    && hasValidKeywords(recipe.searchKeywords);
}

/** Checks complete-recipe nutrition values. */
function hasValidNutrition(nutrition) {
  return Number.isInteger(nutrition?.calories)
    && Number.isInteger(nutrition?.protein)
    && Number.isInteger(nutrition?.carbohydrates)
    && Number.isInteger(nutrition?.fat)
    && Object.values(nutrition).every((value) => value >= 0);
}

/** Checks tag count and simple Title Case formatting. */
function hasValidTags(tags) {
  return tags.length >= 3
    && tags.length <= 5
    && tags.every((tag) => isText(tag) && tag[0] === tag[0].toUpperCase());
}

/** Checks keyword count and lowercase formatting. */
function hasValidKeywords(keywords) {
  return keywords.length >= 5
    && keywords.length <= 10
    && keywords.every(
      (keyword) => isText(keyword) && keyword === keyword.toLowerCase(),
    );
}

/** Checks diet restrictions against every generated ingredient. */
function respectsDiet(recipe, diet) {
  const names = recipe.ingredients.map((item) => item.normalizedName);

  if (diet === 'vegan') {
    return !names.some((name) => VEGAN_FORBIDDEN.has(name));
  }

  if (diet === 'vegetarian') {
    return !names.some((name) => VEGETARIAN_FORBIDDEN.has(name));
  }

  return diet !== 'keto' || !names.some((name) => KETO_FORBIDDEN.has(name));
}

/** Creates a successful validation result. */
function validResult(recipe) {
  return {
    isValid: true,
    error: null,
    recipe,
  };
}

/** Creates one failed validation result. */
function invalidResult(error) {
  return {
    isValid: false,
    error,
    recipe: null,
  };
}

/** Calculates how many requested ingredients are used. */
function getUsedIngredientPercent(recipe, requestData) {
  const requestedNames = requestData.requestedIngredientNames ?? [];
  const requiredNames = recipe.requiredIngredientNames ?? [];

  const usedCount = requestedNames.filter((name) =>
    requiredNames.includes(name),
  ).length;

  return requestedNames.length
    ? Math.round((usedCount / requestedNames.length) * 100)
    : 0;
}

/** Checks whether a name belongs to allowed basic ingredients. */
function isBasic(name) {
  return BASIC_NAMES.has(name);
}

/** Returns unique non-empty string values. */
function unique(values) {
  return [...new Set(values.filter(isText))];
}

/** Checks whether two arrays contain the same unique values. */
function sameMembers(first, second) {
  return first.length === second.length
    && first.every((value) => second.includes(value));
}

/** Calculates used requested ingredient percentage. */
function getPercent(usedNames, requestedNames) {
  return requestedNames.length
    ? Math.round((usedNames.length / requestedNames.length) * 100)
    : 0;
}

/** Builds a duplicate signature from ingredients and cooking steps. */
function getRecipeSignature(recipe) {
  const ingredients = Array.isArray(recipe?.ingredients)
    ? [...new Set(
        recipe.ingredients
          .map((item) => item?.normalizedName)
          .filter(isText),
      )]
        .sort()
        .join('|')
    : '';

  const steps = Array.isArray(recipe?.steps)
    ? recipe.steps
        .map((step) => normalizeText(step?.text))
        .filter(Boolean)
        .join('|')
    : '';

  return ingredients && steps ? `${ingredients}::${steps}` : '';
}

/** Normalizes one recipe title. */
function normalizeTitle(title) {
  return normalizeText(title);
}

/** Normalizes plain text for stable duplicate checks. */
function normalizeText(value) {
  return String(value ?? '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

/** Checks lowercase English kebab-case ingredient names. */
function isNormalizedName(value) {
  return typeof value === 'string'
    && /^[a-z]+(?:-[a-z]+)*$/.test(value);
}

/** Checks one non-empty string. */
function isText(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

const input = $('Code - Validate Generated Recipes').item.json;
const suggestions = $input.first().json ?? {};
const now = new Date().toISOString();

const recipeRecords = input.validRecipes.map((recipe, index) =>
  createRecipeRecord(recipe, input.requestId, index + 1, now),
);

const generatedRecipeIds = recipeRecords.map((recipe) => recipe.id);

const firebaseUpdate = createFirebaseUpdate(
  recipeRecords,
  suggestions,
  now,
);

const resultMatchedRecipeIds = input.matchedRecipeIds.slice(
  0,
  Math.max(0, input.maxResultCount - generatedRecipeIds.length),
);

return [
  {
    json: {
      ...input,
      generatedRecipeIds,
      resultMatchedRecipeIds,
      resultUsedIngredientPercent: Math.max(
        input.matchedUsedIngredientPercent ?? 0,
        input.generatedUsedIngredientPercent ?? 0,
      ),
      firebaseUpdate,
    },
  },
];

/** Creates one complete Firebase recipe record. */
function createRecipeRecord(recipe, requestId, sequence, now) {
  const chefIcons = createChefIcons(recipe.cookingPersons);

  return {
    ...recipe,
    id: `generated-${requestId}-${sequence}`,
    ingredientIndex: createIngredientIndex(recipe.ingredients),
    steps: addChefIcons(recipe.steps, chefIcons),
    chefIcons,
    likes: 0,
    source: 'generated',
    isPublic: true,
    createdAt: now,
    updatedAt: now,
  };
}

/** Creates one atomic Firebase update for all generated recipes. */
function createFirebaseUpdate(recipeRecords, suggestions, now) {
  const updates = {};
  const workingSuggestions = {};

  for (const recipe of recipeRecords) {
    Object.assign(updates, createRecipeUpdates(recipe));

    for (const ingredient of recipe.ingredients) {
      const current = workingSuggestions[ingredient.normalizedName]
        ?? suggestions[ingredient.normalizedName]
        ?? {};

      const sourceRecipeIds = uniqueIds(
        current.sourceRecipeIds ?? [],
        recipe.id,
      );

      const nextSuggestion = {
        approved: current.approved ?? true,
        createdAt: current.createdAt ?? now,
        displayName: current.displayName ?? ingredient.name,
        normalizedName: ingredient.normalizedName,
        sourceRecipeIds,
        updatedAt: now,
        usageCount: sourceRecipeIds.length,
      };

      workingSuggestions[ingredient.normalizedName] = nextSuggestion;
      updates[`ingredientSuggestions/${ingredient.normalizedName}`] =
        nextSuggestion;
    }
  }

  return updates;
}

/** Creates Firebase updates for one recipe and all indexes. */
function createRecipeUpdates(recipe) {
  return {
    [`recipes/${recipe.id}`]: recipe,
    [`publicRecipes/${recipe.id}`]: true,
    [`recipeIndexes/byCuisine/${recipe.cuisine}/${recipe.id}`]: true,
    [`recipeIndexes/byDiet/${recipe.diet}/${recipe.id}`]: true,
    [`recipeIndexes/byCookingTime/${recipe.cookingTime}/${recipe.id}`]: true,
    ...createIngredientIndexUpdates(recipe.ingredients, recipe.id),
  };
}

/** Creates one ingredient index entry for every recipe ingredient. */
function createIngredientIndexUpdates(ingredients, recipeId) {
  return ingredients.reduce((updates, ingredient) => {
    updates[`recipeIndexes/byIngredient/${ingredient.normalizedName}/${recipeId}`] =
      true;

    return updates;
  }, {});
}

/** Creates the Firebase ingredient lookup index. */
function createIngredientIndex(ingredients) {
  return ingredients.reduce((index, ingredient) => {
    index[ingredient.normalizedName] = true;
    return index;
  }, {});
}

/** Creates chef icon paths. */
function createChefIcons(count) {
  const names = ['one', 'two', 'three', 'four'];

  return names
    .slice(0, count)
    .map((name) => `assets/images/svg/chef-${name}.svg`);
}

/** Adds the corresponding chef icon to every cooking step. */
function addChefIcons(steps, chefIcons) {
  return steps.map((step) => ({
    ...step,
    chefIcon: chefIcons[step.chefNumber - 1],
  }));
}

/** Adds a recipe id only once to an ingredient suggestion. */
function uniqueIds(ids, recipeId) {
  return [...new Set([...ids, recipeId])];
}

